-- Kheti Portal database: farmers, plots, crop cycles, diary activities and CFT survey answers.
--
-- Who sees what:
--   * Every signed-in account gets a row in public.staff (created automatically on sign-up).
--     Accounts outside @growindigo.co.in are refused when Supabase tries to create them.
--   * Staff see and edit only the farmers assigned to them in public.farmer_access.
--   * Admins (staff.is_admin) see and edit everything, and are the only ones who can
--     add farmers, plots and crop cycles or change assignments.
--
-- IDs are text and generated by the app, so entries made offline keep their ID when uploaded.

-- ---------- Tables ----------

create table public.staff (
  id uuid primary key references auth.users (id) on delete cascade,
  email text not null unique,
  name text,
  is_admin boolean not null default false,
  created_at timestamptz not null default now()
);

create table public.farmers (
  id text primary key,
  name text not null,
  father_name text,
  village text,
  contact text,
  kisan_advisor text,
  gender text,
  gipl_id text unique,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table public.farmer_access (
  staff_id uuid not null references public.staff (id) on delete cascade,
  farmer_id text not null references public.farmers (id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (staff_id, farmer_id)
);
create index farmer_access_farmer_idx on public.farmer_access (farmer_id);

create table public.plots (
  id text primary key,
  farmer_id text not null references public.farmers (id) on delete cascade,
  acres numeric(10, 2) not null check (acres > 0),
  village text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index plots_farmer_idx on public.plots (farmer_id);

create table public.crop_cycles (
  id text primary key,
  plot_id text not null references public.plots (id) on delete cascade,
  crop text not null,
  season text not null,
  year text not null,
  sowing_date date,
  harvest_date date,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index crop_cycles_plot_idx on public.crop_cycles (plot_id);

create table public.activities (
  id text primary key,
  crop_cycle_id text not null references public.crop_cycles (id) on delete cascade,
  module text not null,
  date date not null,
  notes text,
  payload jsonb not null default '{}'::jsonb,
  created_by uuid references public.staff (id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index activities_cycle_idx on public.activities (crop_cycle_id);

-- One CFT & Regen survey per farmer; answers keep the questionnaire's own IDs (A01, RW-050, ...).
create table public.surveys (
  farmer_id text primary key references public.farmers (id) on delete cascade,
  answers jsonb not null default '{}'::jsonb,
  updated_by uuid references public.staff (id) on delete set null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- ---------- Bookkeeping triggers ----------

create function public.touch_updated_at() returns trigger
language plpgsql set search_path = '' as $$
begin
  new.updated_at := now();
  return new;
end $$;

create trigger farmers_touch before update on public.farmers for each row execute function public.touch_updated_at();
create trigger plots_touch before update on public.plots for each row execute function public.touch_updated_at();
create trigger crop_cycles_touch before update on public.crop_cycles for each row execute function public.touch_updated_at();
create trigger activities_touch before update on public.activities for each row execute function public.touch_updated_at();
create trigger surveys_touch before update on public.surveys for each row execute function public.touch_updated_at();

-- Record who saved a row from the signed-in session, not from what the app sends.
create function public.stamp_activity_author() returns trigger
language plpgsql set search_path = '' as $$
begin
  if tg_op = 'INSERT' then
    new.created_by := auth.uid();
  else
    new.created_by := old.created_by;
  end if;
  return new;
end $$;
create trigger activities_author before insert or update on public.activities for each row execute function public.stamp_activity_author();

create function public.stamp_survey_editor() returns trigger
language plpgsql set search_path = '' as $$
begin
  new.updated_by := auth.uid();
  return new;
end $$;
create trigger surveys_editor before insert or update on public.surveys for each row execute function public.stamp_survey_editor();

-- ---------- Accounts: @growindigo.co.in only ----------

create function public.handle_new_user() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  if new.email is null or lower(new.email) not like '%@growindigo.co.in' then
    raise exception 'Only @growindigo.co.in accounts can use Kheti Portal';
  end if;
  insert into public.staff (id, email, name)
  values (new.id, lower(new.email), coalesce(new.raw_user_meta_data ->> 'full_name', new.raw_user_meta_data ->> 'name'))
  on conflict (id) do nothing;
  return new;
end $$;

create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_user();

-- ---------- Access helpers (security definer so policies don't recurse through RLS) ----------

create function public.is_admin() returns boolean
language sql stable security definer set search_path = '' as $$
  select coalesce((select s.is_admin from public.staff s where s.id = auth.uid()), false)
$$;

create function public.can_access_farmer(fid text) returns boolean
language sql stable security definer set search_path = '' as $$
  select public.is_admin()
      or exists (select 1 from public.farmer_access fa where fa.staff_id = auth.uid() and fa.farmer_id = fid)
$$;

create function public.farmer_of_plot(pid text) returns text
language sql stable security definer set search_path = '' as $$
  select p.farmer_id from public.plots p where p.id = pid
$$;

create function public.farmer_of_cycle(cid text) returns text
language sql stable security definer set search_path = '' as $$
  select p.farmer_id from public.crop_cycles c join public.plots p on p.id = c.plot_id where c.id = cid
$$;

revoke execute on function public.handle_new_user() from public, anon, authenticated;

-- ---------- Row level security ----------

alter table public.staff enable row level security;
alter table public.farmers enable row level security;
alter table public.farmer_access enable row level security;
alter table public.plots enable row level security;
alter table public.crop_cycles enable row level security;
alter table public.activities enable row level security;
alter table public.surveys enable row level security;

-- staff: see yourself; admins see and manage everyone.
create policy staff_read on public.staff for select to authenticated
  using (id = auth.uid() or public.is_admin());
create policy staff_admin on public.staff for update to authenticated
  using (public.is_admin()) with check (public.is_admin());

-- farmer_access: see your own assignments; admins manage them.
create policy access_read on public.farmer_access for select to authenticated
  using (staff_id = auth.uid() or public.is_admin());
create policy access_admin on public.farmer_access for all to authenticated
  using (public.is_admin()) with check (public.is_admin());

-- farmers, plots, crop cycles: assigned staff read; admins write.
create policy farmers_read on public.farmers for select to authenticated
  using (public.can_access_farmer(id));
create policy farmers_admin on public.farmers for all to authenticated
  using (public.is_admin()) with check (public.is_admin());

create policy plots_read on public.plots for select to authenticated
  using (public.can_access_farmer(farmer_id));
create policy plots_admin on public.plots for all to authenticated
  using (public.is_admin()) with check (public.is_admin());

create policy cycles_read on public.crop_cycles for select to authenticated
  using (public.can_access_farmer(public.farmer_of_plot(plot_id)));
create policy cycles_admin on public.crop_cycles for all to authenticated
  using (public.is_admin()) with check (public.is_admin());

-- activities: assigned staff read, add and correct entries; only admins delete.
create policy activities_read on public.activities for select to authenticated
  using (public.can_access_farmer(public.farmer_of_cycle(crop_cycle_id)));
create policy activities_insert on public.activities for insert to authenticated
  with check (public.can_access_farmer(public.farmer_of_cycle(crop_cycle_id)));
create policy activities_update on public.activities for update to authenticated
  using (public.can_access_farmer(public.farmer_of_cycle(crop_cycle_id)))
  with check (public.can_access_farmer(public.farmer_of_cycle(crop_cycle_id)));
create policy activities_delete on public.activities for delete to authenticated
  using (public.is_admin());

-- surveys: assigned staff read and save; only admins delete.
create policy surveys_read on public.surveys for select to authenticated
  using (public.can_access_farmer(farmer_id));
create policy surveys_insert on public.surveys for insert to authenticated
  with check (public.can_access_farmer(farmer_id));
create policy surveys_update on public.surveys for update to authenticated
  using (public.can_access_farmer(farmer_id)) with check (public.can_access_farmer(farmer_id));
create policy surveys_delete on public.surveys for delete to authenticated
  using (public.is_admin());

-- Signed-out visitors get nothing.
revoke all on all tables in schema public from anon;
